<?php namespace App\Services; use App\Models\{TahunAnggaran,Pendapatan,Belanja,Pembiayaan};
class ApbdesaSummary { public function for(TahunAnggaran $year, bool $public=true): array { $scope=fn($q)=>$public?$q->where('status_publikasi','dipublikasikan'):$q; $pend=$scope(Pendapatan::where('tahun_anggaran_id',$year->id)); $bel=$scope(Belanja::where('tahun_anggaran_id',$year->id)); $biaya=$scope(Pembiayaan::where('tahun_anggaran_id',$year->id)); $income=(float)$pend->sum('anggaran'); $expense=(float)$bel->sum('anggaran'); $incomeReal=(float)$pend->withSum(['realisasi'=>fn($q)=>$public?$q->where('status_publikasi','dipublikasikan'):$q],'nilai')->get()->sum('realisasi_sum_nilai'); $expenseReal=(float)$bel->withSum(['realisasi'=>fn($q)=>$public?$q->where('status_publikasi','dipublikasikan'):$q],'nilai')->get()->sum('realisasi_sum_nilai'); $inflow=(float)(clone $biaya)->where('jenis','penerimaan')->sum('anggaran'); $outflow=(float)(clone $biaya)->where('jenis','pengeluaran')->sum('anggaran'); return compact('income','expense','incomeReal','expenseReal','inflow','outflow')+['netFinancing'=>$inflow-$outflow,'surplus'=>$income-$expense,'incomeRate'=>$income?($incomeReal/$income*100):0,'expenseRate'=>$expense?($expenseReal/$expense*100):0,'overallRate'=>($income+$expense)?(($incomeReal+$expenseReal)/($income+$expense)*100):0]; }}
